    { ru: "Я не буду ничего подписывать без переводчика.", pr: "Ya ne budu nichivo patpisivat bis pirivotchika.", uz: "Tarjimonsiz hech narsaga imzo chekmayman." },
    { ru: "Мне нужен адвокат, без него я не буду отвечать.", pr: "Mne nujen advakat, biz nivo ya ne budu atvichat.", uz: "Menga advokat kerak, usiz javob bermayman." },
    { ru: "Можно получить копию протокола?", pr: "Mojna paluchit kopiyu pratakola?", uz: "Bayonnomaning nusxasini olsam bo‘ladimi?" },
    { ru: "Я не согласен с протоколом и напишу об этом.", pr: "Ya ne saglasin s pratakolam i napishu ab etam.", uz: "Bayonnomaga rozi emasman va bu haqda yozib qo‘yaman. (ayol aytsa: «Я не согласна с протоколом…»)" },
    { ru: "У меня в метро вытащили кошелёк из кармана.", pr: "U minya v mitro vitashili kashilyok is karmana.", uz: "Metroda cho‘ntagimdan hamyonimni sug‘urib olishdi." },
    { ru: "Опишите, пожалуйста, как выглядел вор.", pr: "Apishite, pajalusta, kak vigladil vor.", uz: "Iltimos, o‘g‘ri qanday ko‘rinishda bo‘lganini tasvirlab bering." },
    { ru: "Это был молодой мужчина в чёрной куртке.", pr: "Eta bil maladoy mushchina f chyornay kurtke.", uz: "Bu qora kurtka kiygan yosh erkak edi." },
    { ru: "В каком отделении полиции принимают заявления?", pr: "F kakom atdilenii palitsii prinimayut zayavleniya?", uz: "Qaysi politsiya bo‘limida ariza qabul qilishadi?" },
    { ru: "Вам выдадут талон-уведомление о принятии заявления.", pr: "Vam vidadut talon-uvidamleniye a prinyatii zayavleniya.", uz: "Sizga ariza qabul qilingani haqida talon-bildirishnoma berishadi." },
    { ru: "Сосед угрожает мне и моей семье.", pr: "Sased ugrajayet mne i mayey simye.", uz: "Qo‘shni menga va oilamga tahdid qilyapti." },
    { ru: "Работодатель забрал мой паспорт и не отдаёт.", pr: "Rabatadatel zabral moy paspart i ne atdayot.", uz: "Ish beruvchi pasportimni olib qo‘ydi va qaytarmayapti." },
    { ru: "Никто не имеет права забирать ваш паспорт.", pr: "Nikto ne imeyet prava zabirat vash paspart.", uz: "Hech kim pasportingizni olib qo‘yishga haqli emas." },
    { ru: "Меня оскорбили из-за национальности.", pr: "Minya askarbili iz-za natsianalnasti.", uz: "Meni millatim tufayli haqorat qilishdi." },
    { ru: "Есть ли свидетели происшествия?", pr: "Yest li svideteli praisshestviya?", uz: "Hodisaning guvohlari bormi?" },
    { ru: "Я видел драку у магазина и могу быть свидетелем.", pr: "Ya videl draku u magazina i magu bit svidetilem.", uz: "Do‘kon oldidagi mushtlashuvni ko‘rdim, guvoh bo‘la olaman. (ayol aytsa: «Я видела драку… и могу быть свидетельницей»)" },
    { ru: "За что мне выписали штраф?", pr: "Za shto mne vipisali shtraf?", uz: "Menga nima uchun jarima yozishdi?" },
    { ru: "Штраф можно оплатить со скидкой в течение двадцати дней.", pr: "Shtraf mojna aplatit sa skitkay f tichyeniye dvatsati dney.", uz: "Jarimani yigirma kun ichida chegirma bilan to‘lash mumkin." },
    { ru: "Куда обратиться, если права мигранта нарушены?", pr: "Kuda abratitsa, yesli prava migranta narusheni?", uz: "Migrant huquqlari buzilsa, qayerga murojaat qilish kerak?" },
    { ru: "Можно позвонить на горячую линию консульства.", pr: "Mojna pazvanit na garyachuyu liniyu konsulstva.", uz: "Konsullikning ishonch telefoniga qo‘ng‘iroq qilish mumkin." },
    { ru: "Говорите спокойно и вежливо, не спорьте с полицейским на улице.", pr: "Gavarite spakoyna i vejliva, ne sporte s palitseyskim na ulitse.", uz: "Xotirjam va muloyim gapiring, ko‘chada politsiyachi bilan bahslashmang." },
    { ru: "Спасибо, что быстро приехали.", pr: "Spasiba, shto bistra priyexali.", uz: "Tez yetib kelganingiz uchun rahmat." }
